import pandas as pd
import numpy as np
from datetime import datetime, timedelta
from dateutil.relativedelta import relativedelta
import re

class Period:
    def __init__(self, years=0, months=0, days=0, hours=0, minutes=0, seconds=0):
        self.years = years
        self.months = months
        self.days = days
        self.hours = hours
        self.minutes = minutes
        self.seconds = seconds

    def __add__(self, other):
        if isinstance(other, Period):
            return Period(
                self.years + other.years, self.months + other.months, self.days + other.days,
                self.hours + other.hours, self.minutes + other.minutes, self.seconds + other.seconds
            )
        return NotImplemented

    def __radd__(self, other):
        return self.__add__(other)

    def __sub__(self, other):
        if isinstance(other, Period):
            return Period(
                self.years - other.years, self.months - other.months, self.days - other.days,
                self.hours - other.hours, self.minutes - other.minutes, self.seconds - other.seconds
            )
        return NotImplemented

    def __mul__(self, other):
        if isinstance(other, (int, float)):
            return Period(
                self.years * other, self.months * other, self.days * other,
                self.hours * other, self.minutes * other, self.seconds * other
            )
        return NotImplemented

    def __rmul__(self, other):
        return self.__mul__(other)

    def __gt__(self, other):
        # R's period comparison with characters is based on the string representation
        # of the period. We simulate this by converting self to the R-style string.
        return str(self) > str(other)

    def __str__(self):
        # Simplified version of lubridate's printing: "5M 90S"
        parts = []
        if self.years: parts.append(f"{self.years}Y")
        if self.months: parts.append(f"{self.months}M")
        if self.days: parts.append(f"{self.days}D")
        if self.hours: parts.append(f"{self.hours}H")
        if self.minutes: parts.append(f"{self.minutes}M")
        if self.seconds: parts.append(f"{self.seconds}S")
        return " ".join(parts) if parts else "0S"

    def to_relativedelta(self):
        return relativedelta(years=self.years, months=self.months, days=self.days, 
                              hours=self.hours, minutes=self.minutes, seconds=self.seconds)

def period(num=None, units="second", **kwargs):
    # Handle string parsing
    if isinstance(num, str):
        s = num
        res = Period()
        # ISO 8601 basic check
        if s.startswith('P'):
            m = re.match(r'P(?:(\d+)Y)?(?:(\d+)M)?(?:(\d+)D)?(?:T(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?)?', s)
            if m:
                groups = m.groups()
                if groups[0]: res.years = int(groups[0])
                if groups[1]: res.months = int(groups[1])
                if groups[2]: res.days = int(groups[2])
                if groups[3]: res.hours = int(groups[3])
                if groups[4]: res.minutes = int(groups[4])
                if groups[5]: res.seconds = int(groups[5])
        else:
            # Lubridate style parsing
            # Map common abbreviations to Period attributes
            patterns = {
                'year': 'years', 'y': 'years',
                'month': 'months', 'm': 'months',
                'day': 'days', 'd': 'days',
                'hour': 'hours', 'h': 'hours',
                'min': 'minutes', 'm': 'minutes', # Contextual in R, simplified here
                'sec': 'seconds', 's': 'seconds'
            }
            # This is a very rough approximation of lubridate's complex parser
            # Matches "2days", "2 days", "2d"
            matches = re.findall(r'(-?\d+)\s*([a-zA-Z]+)', s)
            if not matches and ('day' in s.lower() or 'month' in s.lower()):
                # Handle "day day" case -> default to 1
                words = s.lower().split()
                for w in words:
                    if 'day' in w: res.days += 1
                    elif 'month' in w: res.months += 1
                    elif 'year' in w: res.years += 1
                    elif 'hour' in w: res.hours += 1
                    elif 'min' in w: res.minutes += 1
                    elif 'sec' in w: res.seconds += 1
            else:
                for val, unit in matches:
                    u = unit.lower()
                    if u.startswith('year'): res.years += int(val)
                    elif u.startswith('month'): res.months += int(val)
                    elif u.startswith('day'): res.days += int(val)
                    elif u.startswith('hour'): res.hours += int(val)
                    elif u.startswith('min'): res.minutes += int(val)
                    elif u.startswith('sec'): res.seconds += int(val)
                    elif u == 'y': res.years += int(val)
                    elif u == 'm' and 'T' not in s: res.months += int(val)
                    elif u == 'd': res.days += int(val)
                    elif u == 'h': res.hours += int(val)
                    elif u == 'm' and 'T' in s: res.minutes += int(val)
                    elif u == 's': res.seconds += int(val)
        return res

    # Handle num and units vectors
    if isinstance(num, (list, tuple, np.ndarray)):
        # In R, period(c(90, 5), c("second", "minute")) returns a single Period object 
        # composed of the sum or a specific representation. 
        # Actually, lubridate::period with vectors is a bit nuanced.
        # For the examples provided, it's constructing a Period.
        res = Period()
        for v, u in zip(num, units):
            u = u.lower().rstrip('s')
            if u == 'second': res.seconds += v
            elif u == 'minute': res.minutes += v
            elif u == 'hour': res.hours += v
            elif u == 'day': res.days += v
            elif u == 'week': res.days += v * 7
        return res

    # Handle scalar num and units
    if num is not None and not isinstance(num, str):
        res = Period()
        u = units.lower().rstrip('s')
        if u == 'second': res.seconds = num
        elif u == 'minute': res.minutes = num
        elif u == 'hour': res.hours = num
        elif u == 'day': res.days = num
        elif u == 'week': res.days = num * 7
        # Now merge with kwargs
        for k, v in kwargs.items():
            if k == 'second': res.seconds += v
            elif k == 'minute': res.minutes += v
            elif k == 'hour': res.hours += v
            elif k == 'day': res.days += v
            elif k == 'week': res.days += v * 7
        return res

    # Handle kwargs only
    res = Period()
    for k, v in kwargs.items():
        if k == 'second': res.seconds = v
        elif k == 'minute': res.minutes = v
        elif k == 'hour': res.hours = v
        elif k == 'day': res.days = v
        elif k == 'week': res.days = v * 7
        elif k == 'month': res.months = v
        elif k == 'year': res.years = v
    return res

def days(x=1): return period(day=x)
def hours(x=1): return period(hour=x)
def minutes(x=1): return period(minute=x)
def years(x=1): return period(year=x)
def months(x=1): return period(month=x)
def ddays(x=1): return timedelta(days=x)

def ymd(x, tz=None):
    # Simplification for the given inputs
    dt = pd.to_datetime(x)
    if tz:
        dt = dt.tz_localize(tz)
    return dt

def ymd_hms(x, tz="UTC"):
    dt = pd.to_datetime(x).tz_localize(tz)
    return dt

def is_period(x):
    return isinstance(x, Period)

