# Separate period and units vectors
period([90, 5], ["second", "minute"])
period(-1, "days")
period([3, 1, 2, 13, 1], ["second", "minute", "hour", "day", "week"])
period([1, -60], ["hour", "minute"])
period(0, "second")

# Units as arguments
period(second=90, minute=5)
period(day=-1)
period(second=3, minute=1, hour=2, day=13, week=1)
period(hour=1, minute=-60)
period(second=0)
# Note: In R, period(c(1, -60), c("hour", "minute"), hour = c(1, 2), minute = c(3, 4))
# This is a complex case. We'll approximate it.
period([1, -60], ["hour", "minute"], hour=[1, 2], minute=[3, 4])

# Lubridate style parsing
period("2M 1sec")
period("2hours 2minutes 1second")
period("2d 2H 2M 2S")
period("2days 2hours 2mins 2secs")
period("2 days, 2 hours, 2 mins, 2 secs")
period("day day")

# ISO 8601 parsing
period("P10M23DT23H")
period("10DT10M")
period("P3Y6M4DT12H30M5S")
period("P23DT60H 20min 100 sec")

# Comparison
print(period("day 2 sec") > "day 1sec")

# Elementary Constructors
x = ymd("2009-08-03")
p1 = days(1) + hours(6) + minutes(30)
x_res1 = x + p1.to_relativedelta()
p2 = days(100) - hours(8)
x_res2 = x + p2.to_relativedelta()

date_val = pd.to_datetime("2009-08-09").date()
res_date = date_val + timedelta(days=1)
print(type(res_date))

res_hours = pd.to_datetime("2009-08-09") + relativedelta(hours=12)
print(type(res_hours))

# years(1) - months(7)
p3 = years(1) - months(7)
# c(1:3) * hours(1)
h1 = hours(1)
res_mult = [i * h1 for i in range(1, 4)]
# hours(1:3)
res_h_vec = [hours(i) for i in range(1, 4)]

y = ymd(090101) # Note: 090101 is an int in R, handled by ymd
y = pd.to_datetime("2009-01-01")
y_months = [y + months(i).to_relativedelta() for i in range(12)]

boundary = ymd_hms("2009-03-08 01:59:59", tz="America/Chicago")
boundary_p = boundary + days(1).to_relativedelta()
boundary_d = boundary + ddays(1)

