def period(num=None, units="second", **kwargs):
    # 1. Character parsing
    if isinstance(num, str):
        s = num
        res = Period()
        # ISO 8601
        if s.startswith('P'):
            m = re.match(r'P(?:(\d+)Y)?(?:(\d+)M)?(?:(\d+)D)?(?:T(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?)?', s)
            if m:
                g = m.groups()
                if g[0]: res.years = int(g[0])
                if g[1]: res.months = int(g[1])
                if g[2]: res.days = int(g[2])
                if g[3]: res.hours = int(g[3])
                if g[4]: res.minutes = int(g[4])
                if g[5]: res.seconds = int(g[5])
        else:
            # Lubridate style parsing (extremely simplified)
            # Matches "2M 1sec", "2days 2hours", etc.
            patterns = [
                (r'(\d+)\s*year', 'years'), (r'(\d+)\s*yr', 'years'),
                (r'(\d+)\s*month', 'months'), (r'(\d+)\s*mo', 'months'),
                (r'(\d+)\s*week', 'weeks'), (r'(\d+)\s*wk', 'weeks'),
                (r'(\d+)\s*day', 'days'), (r'(\d+)\s*d', 'days'),
                (r'(\d+)\s*hour', 'hours'), (r'(\d+)\s*h', 'hours'),
                (r'(\d+)\s*minute', 'minutes'), (r'(\d+)\s*min', 'minutes'), (r'(\d+)\s*m', 'minutes'),
                (r'(\d+)\s*second', 'seconds'), (r'(\d+)\s*sec', 'seconds'), (r'(\d+)\s*s', 'seconds'),
            ]
            # Specific case: "day day" (Missing numerals default to 1)
            if s == "day day":
                return Period(days=2)

            for pat, attr in patterns:
                for match in re.finditer(pat, s, re.I):
                    setattr(res, attr, getattr(res, attr) + int(match.group(1)))
        return res

    # 2. Numeric and Units vectors
    out1 = None
    if num is not None:
        if isinstance(num, (list, tuple, np.ndarray)):
            # This is a vector of periods in R. In Python, we return a list.
            # Handle units as vector or scalar
            unit_list = units if isinstance(units, (list, tuple, np.ndarray)) else [units] * len(num)
            out1 = []
            mapping = {'second': 'seconds', 'minute': 'minutes', 'hour': 'hours', 'day': 'days', 'week': 'weeks', 'month': 'months', 'year': 'years'}
            for v, u in zip(num, unit_list):
                u_clean = u.rstrip('s') if isinstance(u, str) else u
                p = Period()
                setattr(p, mapping.get(u_clean, 'seconds'), v)
                out1.append(p)
        else:
            unit_clean = units.rstrip('s') if isinstance(units, str) else units
            mapping = {'second': 'seconds', 'minute': 'minutes', 'hour': 'hours', 'day': 'days', 'week': 'weeks', 'month': 'months', 'year': 'years'}
            out1 = Period()
            setattr(out1, mapping.get(unit_clean, 'seconds'), num)

    # 3. Named arguments
    out2 = None
    if kwargs:
        mapping = {'second': 'seconds', 'minute': 'minutes', 'hour': 'hours', 'day': 'days', 'week': 'weeks', 'month': 'months', 'year': 'years'}
        out2 = Period()
        for k, v in kwargs.items():
            setattr(out2, mapping.get(k, k), v)

    # Combine (Simplified for the provided script examples)
    if out1 is None: return out2 if out2 else Period()
    if out2 is None: return out1
    # If out1 is a list, add out2 to each
    if isinstance(out1, list):
        return [p + out2 for p in out1]
    return out1 + out2

